import React, { useState, useEffect } from 'react';
import axios from 'axios';
import './ContentManager.css';

function ContentManager({ user }) {
  const [settings, setSettings] = useState(null);
  const [activeTab, setActiveTab] = useState('general');
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [message, setMessage] = useState('');
  const [logoPreview, setLogoPreview] = useState(null);

  useEffect(() => {
    fetchSettings();
  }, []);

  const fetchSettings = async () => {
    try {
      const token = localStorage.getItem('token');
      const response = await axios.get('http://localhost:5000/api/settings', {
        headers: { Authorization: `Bearer ${token}` },
      });
      setSettings(response.data);
      if (response.data.logo?.url) {
        setLogoPreview(response.data.logo.url);
      }
      setLoading(false);
    } catch (error) {
      console.error('Error fetching settings:', error);
      setLoading(false);
    }
  };

  const handleSaveSettings = async () => {
    try {
      setSaving(true);
      const token = localStorage.getItem('token');
      await axios.put('http://localhost:5000/api/settings', settings, {
        headers: { Authorization: `Bearer ${token}` },
      });
      setMessage('Settings saved successfully!');
      setTimeout(() => setMessage(''), 3000);
    } catch (error) {
      setMessage('Error saving settings: ' + (error.response?.data?.message || error.message));
    } finally {
      setSaving(false);
    }
  };

  const handleLogoUpload = async (e) => {
    const file = e.target.files[0];
    if (!file) return;

    const formData = new FormData();
    formData.append('logo', file);

    try {
      const token = localStorage.getItem('token');
      const response = await axios.post('http://localhost:5000/api/settings/logo/upload', formData, {
        headers: {
          Authorization: `Bearer ${token}`,
          'Content-Type': 'multipart/form-data',
        },
      });
      setMessage('Logo uploaded successfully!');
      setLogoPreview(response.data.url);
      fetchSettings();
    } catch (error) {
      setMessage('Error uploading logo: ' + (error.response?.data?.message || error.message));
    }
  };

  const handleUpdateSection = (section, field, value) => {
    setSettings((prev) => ({
      ...prev,
      [section]: { ...prev[section], [field]: value },
    }));
  };

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    const keys = name.split('.');

    if (keys.length === 1) {
      setSettings((prev) => ({ ...prev, [name]: value }));
    } else {
      handleUpdateSection(keys[0], keys[1], value);
    }
  };

  if (loading) return <div className="content-manager-loading">Loading settings...</div>;
  if (!settings) return <div className="content-manager-loading">Settings not available</div>;

  return (
    <div className="content-manager">
      <div className="wrap">
        <div className="content-manager-header">
          <h1 className="display">Content Manager</h1>
          <p>Manage website branding, SEO, header, footer and content blocks</p>
        </div>

        {message && <div className={`message ${message.includes('Error') ? 'error' : 'success'}`}>{message}</div>}

        <div className="content-tabs">
          <button className={`tab-btn ${activeTab === 'general' ? 'active' : ''}`} onClick={() => setActiveTab('general')}>General</button>
          <button className={`tab-btn ${activeTab === 'hero' ? 'active' : ''}`} onClick={() => setActiveTab('hero')}>Hero</button>
          <button className={`tab-btn ${activeTab === 'pricing' ? 'active' : ''}`} onClick={() => setActiveTab('pricing')}>Pricing</button>
          <button className={`tab-btn ${activeTab === 'features' ? 'active' : ''}`} onClick={() => setActiveTab('features')}>Features</button>
          <button className={`tab-btn ${activeTab === 'footer' ? 'active' : ''}`} onClick={() => setActiveTab('footer')}>Footer</button>
          <button className={`tab-btn ${activeTab === 'branding' ? 'active' : ''}`} onClick={() => setActiveTab('branding')}>Branding</button>
          <button className={`tab-btn ${activeTab === 'seo' ? 'active' : ''}`} onClick={() => setActiveTab('seo')}>SEO</button>
          <button className={`tab-btn ${activeTab === 'maintenance' ? 'active' : ''}`} onClick={() => setActiveTab('maintenance')}>Maintenance</button>
        </div>

        <div className="content-panel">
          {activeTab === 'general' && (
            <div className="section">
              <h2>General Settings</h2>
              <div className="form-group">
                <label>Site Name</label>
                <input type="text" name="siteName" value={settings.siteName || ''} onChange={handleInputChange} />
              </div>
              <div className="form-group">
                <label>Site Title</label>
                <input type="text" name="siteTitle" value={settings.siteTitle || ''} onChange={handleInputChange} />
              </div>
              <div className="form-group">
                <label>Site Description</label>
                <textarea name="siteDescription" value={settings.siteDescription || ''} onChange={handleInputChange} rows="4" />
              </div>
              <div className="form-group">
                <label>Logo Upload</label>
                <div className="logo-upload">
                  {logoPreview && <div className="logo-preview"><img src={logoPreview.startsWith('http') ? logoPreview : `http://localhost:5000${logoPreview}`} alt="Logo" /></div>}
                  <input type="file" accept="image/*" onChange={handleLogoUpload} />
                </div>
              </div>
            </div>
          )}

          {activeTab === 'hero' && (
            <div className="section">
              <h2>Hero Section</h2>
              <div className="toggle-group">
                <label>
                  <input type="checkbox" checked={settings.heroSection?.enabled || false} onChange={(e) => handleUpdateSection('heroSection', 'enabled', e.target.checked)} />
                  Enable Hero Section
                </label>
              </div>
              <div className="form-group">
                <label>Hero Title</label>
                <input type="text" value={settings.heroSection?.title || ''} onChange={(e) => handleUpdateSection('heroSection', 'title', e.target.value)} />
              </div>
              <div className="form-group">
                <label>Hero Subtitle</label>
                <textarea value={settings.heroSection?.subtitle || ''} onChange={(e) => handleUpdateSection('heroSection', 'subtitle', e.target.value)} rows="3" />
              </div>
              <div className="form-group">
                <label>CTA Text</label>
                <input type="text" value={settings.heroSection?.ctaText || ''} onChange={(e) => handleUpdateSection('heroSection', 'ctaText', e.target.value)} />
              </div>
            </div>
          )}

          {activeTab === 'pricing' && (
            <div className="section">
              <h2>Pricing</h2>
              <div className="toggle-group">
                <label>
                  <input type="checkbox" checked={settings.pricingSection?.enabled || false} onChange={(e) => handleUpdateSection('pricingSection', 'enabled', e.target.checked)} />
                  Enable pricing section
                </label>
              </div>
              <div className="form-group">
                <label>Section Title</label>
                <input type="text" value={settings.pricingSection?.title || ''} onChange={(e) => handleUpdateSection('pricingSection', 'title', e.target.value)} />
              </div>
            </div>
          )}

          {activeTab === 'features' && (
            <div className="section">
              <h2>Features</h2>
              <div className="toggle-group">
                <label>
                  <input type="checkbox" checked={settings.featuresSection?.enabled || false} onChange={(e) => handleUpdateSection('featuresSection', 'enabled', e.target.checked)} />
                  Enable features section
                </label>
              </div>
              <div className="form-group">
                <label>Section Title</label>
                <input type="text" value={settings.featuresSection?.title || ''} onChange={(e) => handleUpdateSection('featuresSection', 'title', e.target.value)} />
              </div>
            </div>
          )}

          {activeTab === 'footer' && (
            <div className="section">
              <h2>Footer</h2>
              <div className="form-group">
                <label>Company Name</label>
                <input type="text" value={settings.footerSection?.companyName || ''} onChange={(e) => handleUpdateSection('footerSection', 'companyName', e.target.value)} />
              </div>
              <div className="form-group">
                <label>Footer Text</label>
                <input type="text" value={settings.footerSection?.footerText || ''} onChange={(e) => handleUpdateSection('footerSection', 'footerText', e.target.value)} />
              </div>
            </div>
          )}

          {activeTab === 'branding' && (
            <div className="section">
              <h2>Branding</h2>
              <div className="colors-grid">
                <div className="form-group">
                  <label>Primary Color</label>
                  <div className="color-picker">
                    <input type="color" value={settings.colors?.primary || '#8b5cf6'} onChange={(e) => setSettings({ ...settings, colors: { ...settings.colors, primary: e.target.value } })} />
                    <span>{settings.colors?.primary || '#8b5cf6'}</span>
                  </div>
                </div>
                <div className="form-group">
                  <label>Secondary Color</label>
                  <div className="color-picker">
                    <input type="color" value={settings.colors?.secondary || '#3b82f6'} onChange={(e) => setSettings({ ...settings, colors: { ...settings.colors, secondary: e.target.value } })} />
                    <span>{settings.colors?.secondary || '#3b82f6'}</span>
                  </div>
                </div>
              </div>
            </div>
          )}

          {activeTab === 'seo' && (
            <div className="section">
              <h2>SEO</h2>
              <div className="form-group">
                <label>Meta Title</label>
                <input type="text" value={settings.seo?.metaTitle || ''} onChange={(e) => handleUpdateSection('seo', 'metaTitle', e.target.value)} />
              </div>
              <div className="form-group">
                <label>Meta Description</label>
                <textarea value={settings.seo?.metaDescription || ''} onChange={(e) => handleUpdateSection('seo', 'metaDescription', e.target.value)} rows="4" />
              </div>
              <div className="form-group">
                <label>Keywords</label>
                <input type="text" value={settings.seo?.keywords || ''} onChange={(e) => handleUpdateSection('seo', 'keywords', e.target.value)} />
              </div>
            </div>
          )}

          {activeTab === 'maintenance' && (
            <div className="section">
              <h2>Maintenance</h2>
              <div className="toggle-group">
                <label>
                  <input type="checkbox" checked={settings.maintenance?.enabled || false} onChange={(e) => handleUpdateSection('maintenance', 'enabled', e.target.checked)} />
                  Enable maintenance mode
                </label>
              </div>
              {settings.maintenance?.enabled && (
                <div className="form-group">
                  <label>Maintenance Message</label>
                  <textarea value={settings.maintenance?.message || ''} onChange={(e) => handleUpdateSection('maintenance', 'message', e.target.value)} rows="4" />
                </div>
              )}
            </div>
          )}
        </div>

        <div className="actions">
          <button className="btn-primary" onClick={handleSaveSettings} disabled={saving}>{saving ? 'Saving...' : 'Save Changes'}</button>
          <button className="btn-secondary" onClick={fetchSettings}>Discard</button>
        </div>
      </div>
    </div>
  );
}

export default ContentManager;
